def match(pattern: str, text: str) -> bool:
    """
    Implements a recursive backtracking algorithm for basic regex matching.
    Supports literal characters, '.', '*', and '+'.
    """

    def is_match(i: int, j: int) -> bool:
        if j == len(pattern):
            return i == len(text)

        first_match = (i < len(text)) and (pattern[j] == text[i] or pattern[j] == '.')

        if j + 1 < len(pattern) and pattern[j + 1] in '*+':
            if pattern[j + 1] == '*':
                return (is_match(i, j + 2) or 
                        (first_match and is_match(i + 1, j)))
            elif pattern[j + 1] == '+':
                return first_match and (is_match(i + 1, j) or
                                        is_match(i + 1, j + 2))
        elif first_match:
            return is_match(i + 1, j + 1)

        return False

    return is_match(0, 0)

