    """
    Implements a dynamic programming algorithm for basic regex matching.
    Supports literal characters, '.', '*', and '+'.
    """

    m, n = len(text), len(pattern)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    for j in range(1, n + 1):
        if pattern[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            first_match = (text[i - 1] == pattern[j - 1] or pattern[j - 1] == '.')

