                dp[i][j] = dp[i][j - 2] or (first_match and dp[i - 1][j])
            elif pattern[j - 1] == '+':
                dp[i][j] = first_match and (dp[i - 1][j] or (i > 1 and dp[i - 1][j - 1]))
            else:
                dp[i][j] = first_match and dp[i - 1][j - 1]

    return dp[m][n]

